mapper.select:
SELECT H.table_id, H.account_id, H.account_name, H.table_name, H.table_year, H.table_month, H.table_week, H.source, H.user_id, DATE_FORMAT(H.created_at, '%Y-%m-%d %H:%i:%s') AS created_at, DATE_FORMAT(H.mod_at, '%Y-%m-%d %H:%i:%s') AS mod_at FROM the_full_order.tb_account_table_meals H WHERE 1 = 1
AND H.account_id = #{account_id}
AND H.table_id = #{table_id}
AND H.table_year = #{table_year}
AND H.table_month = #{table_month}
AND H.table_week = #{table_week}
ORDER BY H.table_year DESC, H.table_month DESC, H.table_week DESC

SELECT H.table_id, H.account_id, H.account_name, H.table_name, H.table_year, H.table_month, H.table_week, H.source, H.user_id, DATE_FORMAT(H.created_at, '%Y-%m-%d %H:%i:%s') AS created_at, DATE_FORMAT(H.mod_at, '%Y-%m-%d %H:%i:%s') AS mod_at, D.meal_date, D.weekday, D.meal_slot, D.sort_order, D.menu_id, D.menu_name, D.food_type, D.menu_type, D.menu_gubun FROM the_full_order.tb_account_table_meals H LEFT JOIN the_full_order.tb_account_table_meals_detail D ON D.table_id = H.table_id WHERE 1 = 1
AND H.account_id = #{account_id}
AND H.table_id = #{table_id}
ORDER BY H.table_year DESC, H.table_month DESC, H.table_week DESC, D.meal_date, D.meal_slot, D.sort_order
